import { readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { compile } from "json-schema-to-typescript";
import { format, resolveConfig } from "prettier";
import { listSchemaFiles, schemasDir } from "./schema-files.ts";

const generatedDir = resolve(import.meta.dirname, "../src/generated");
const BANNER =
  "// GENERATED by packages/contracts/scripts/gen.ts from contracts/schemas. Do not edit.";

async function prettier(source: string, filePath: string): Promise<string> {
  const config = await resolveConfig(filePath);
  return format(source, { ...config, filepath: filePath });
}

/** Builds every generated file in memory: path -> content. */
export async function generate(): Promise<Map<string, string>> {
  const out = new Map<string, string>();
  const entries: string[] = [];
  const ids: string[] = [];
  for (const file of listSchemaFiles()) {
    const schema = JSON.parse(readFileSync(resolve(schemasDir, file.relPath), "utf8")) as Record<
      string,
      unknown
    >;
    const typesPath = resolve(generatedDir, `${file.name}.v${String(file.version)}.ts`);
    const types = await compile(schema, file.id, {
      bannerComment: BANNER,
      additionalProperties: false,
      unknownAny: true,
      format: false,
      declareExternallyReferenced: true,
    });
    out.set(typesPath, await prettier(types, typesPath));
    ids.push(JSON.stringify(file.id));
    // JSON.parse (not an object literal) so that every key, including "__proto__", stays an own
    // data key exactly as in the canonical file (CP2 review M3).
    entries.push(
      `${JSON.stringify(file.id)}: JSON.parse(${JSON.stringify(JSON.stringify(schema))}) as Record<string, unknown>,`,
    );
  }
  const schemasPath = resolve(generatedDir, "schemas.ts");
  const schemasSource = [
    BANNER,
    "",
    `export type SchemaId = ${ids.join(" | ")};`,
    "",
    "export const schemas: Readonly<Record<SchemaId, Readonly<Record<string, unknown>>>> = {",
    ...entries,
    "};",
    "",
  ].join("\n");
  out.set(schemasPath, await prettier(schemasSource, schemasPath));
  return out;
}

function readOrEmpty(path: string): string {
  try {
    return readFileSync(path, "utf8");
  } catch {
    return "";
  }
}

if (import.meta.main) {
  const check = process.argv.includes("--check");
  const files = await generate();
  const drift = [...files].filter(([path, content]) => readOrEmpty(path) !== content);
  const orphans = readdirSync(generatedDir)
    .map((name) => resolve(generatedDir, name))
    .filter((path) => !files.has(path));
  if (check) {
    for (const [path] of drift) console.error(`generated file out of date: ${path}`);
    for (const path of orphans) console.error(`orphaned generated file: ${path}`);
    if (drift.length > 0 || orphans.length > 0) process.exit(1);
    console.log(`gen:check OK (${String(files.size)} generated files)`);
  } else {
    for (const [path, content] of drift) writeFileSync(path, content);
    for (const path of orphans) rmSync(path);
    console.log(
      `gen: wrote ${String(drift.length)} of ${String(files.size)} files, removed ${String(orphans.length)} orphans`,
    );
  }
}
